export enum Platform {
    Macos,
    Windows,
    Linux
}

const FfiConverterTypePlatform = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = Platform;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return Platform.Macos;
                case 2: return Platform.Windows;
                case 3: return Platform.Linux;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case Platform.Macos: return ordinalConverter.write(1, into);
                case Platform.Windows: return ordinalConverter.write(2, into);
                case Platform.Linux: return ordinalConverter.write(3, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

